        for j in range(w):
            if grid[i][j] != bg and not visited[i][j]:
                # Get connected component
                comp = []
                q = [(i,j)]
                visited[i][j] = True

                while q:
                    ci, cj = q.pop(0)
                    val = grid[ci][cj]
